void nvfs_init_format (void)
{
  UInt16 addr ;

  NVFS_Header nvfs_header ;

  nvfs_header.format_type = NVFS_FORMAT_TYPE_1_00 ;

  nvfs_header.mem.list.root = 0 ;
  nvfs_header.mem.list.last = 0 ;

  nvfs_range_check (nvfs_header.mem.free = nvfs_vars.nvram.beg + sizeof nvfs_header) ;

  nvfs_wr_header (& nvfs_header) ;
}

